use super::misc::determinant_3x3;
use super::misc::min_edge_length;
use super::triangle::triangle_area_3d;
use crate::mesh::types::{ElementType, Mesh, Point};

/// Compute the incenter of a tetrahedron
#[allow(dead_code)]
fn tetrahedron_incenter(verts: &[Point; 4]) -> Point {
    let areas = [
        triangle_area_3d(&verts[1], &verts[2], &verts[3]),
        triangle_area_3d(&verts[0], &verts[2], &verts[3]),
        triangle_area_3d(&verts[0], &verts[1], &verts[3]),
        triangle_area_3d(&verts[0], &verts[1], &verts[2]),
    ];
    let total: f64 = areas.iter().sum();

    let mut cx = 0.0;
    let mut cy = 0.0;
    let mut cz = 0.0;
    for (i, v) in verts.iter().enumerate() {
        let w = areas[i] / total;
        cx += w * v.x;
        cy += w * v.y;
        cz += w * v.z;
    }

    Point::new_3d(cx, cy, cz)
}

/// Compute circumradius of a tetrahedron
pub(super) fn tetrahedron_circumradius(verts: &[Point; 4]) -> f64 {
    let a1 = verts[1].x - verts[0].x;
    let b1 = verts[1].y - verts[0].y;
    let c1 = verts[1].z - verts[0].z;
    let d1 = a1 * a1 + b1 * b1 + c1 * c1;

    let a2 = verts[2].x - verts[0].x;
    let b2 = verts[2].y - verts[0].y;
    let c2 = verts[2].z - verts[0].z;
    let d2 = a2 * a2 + b2 * b2 + c2 * c2;

    let a3 = verts[3].x - verts[0].x;
    let b3 = verts[3].y - verts[0].y;
    let c3 = verts[3].z - verts[0].z;
    let d3 = a3 * a3 + b3 * b3 + c3 * c3;

    let det = determinant_3x3(a1, b1, c1, a2, b2, c2, a3, b3, c3);

    if det.abs() < 1e-12 {
        return f64::INFINITY;
    }

    let ux = determinant_3x3(d1, b1, c1, d2, b2, c2, d3, b3, c3);
    let uy = determinant_3x3(a1, d1, c1, a2, d2, c2, a3, d3, c3);
    let uz = determinant_3x3(a1, b1, d1, a2, b2, d2, a3, b3, d3);

    let num = (ux * ux + uy * uy + uz * uz).sqrt();
    let denom = 2.0 * det.abs();

    num / denom
}

/// Quality metric: ratio of circumradius to minimum edge length
pub(super) fn tetrahedron_quality(verts: &[Point; 4]) -> f64 {
    let r = tetrahedron_circumradius(verts);
    let l_min = min_edge_length(verts);

    if l_min < 1e-12 {
        return 0.0;
    }

    r / l_min
}

/// Circumcentre of a tetrahedron, or `None` when the tet is degenerate.
pub(super) fn tetrahedron_circumcenter(verts: &[Point; 4]) -> Option<Point> {
    let a = (
        verts[1].x - verts[0].x,
        verts[1].y - verts[0].y,
        verts[1].z - verts[0].z,
    );
    let b = (
        verts[2].x - verts[0].x,
        verts[2].y - verts[0].y,
        verts[2].z - verts[0].z,
    );
    let c = (
        verts[3].x - verts[0].x,
        verts[3].y - verts[0].y,
        verts[3].z - verts[0].z,
    );
    let cross = |u: (f64, f64, f64), v: (f64, f64, f64)| {
        (
            u.1 * v.2 - u.2 * v.1,
            u.2 * v.0 - u.0 * v.2,
            u.0 * v.1 - u.1 * v.0,
        )
    };
    let dot = |u: (f64, f64, f64), v: (f64, f64, f64)| u.0 * v.0 + u.1 * v.1 + u.2 * v.2;
    let scale = |u: (f64, f64, f64), s: f64| (u.0 * s, u.1 * s, u.2 * s);
    let add = |u: (f64, f64, f64), v: (f64, f64, f64)| (u.0 + v.0, u.1 + v.1, u.2 + v.2);

    let bxc = cross(b, c);
    let cxa = cross(c, a);
    let axb = cross(a, b);
    let denom = 2.0 * dot(a, bxc);
    if denom.abs() < 1e-20 {
        return None;
    }
    let a2 = dot(a, a);
    let b2 = dot(b, b);
    let c2 = dot(c, c);
    let num = add(add(scale(bxc, a2), scale(cxa, b2)), scale(axb, c2));
    let inv = 1.0 / denom;
    Some(Point::new_3d(
        verts[0].x + num.0 * inv,
        verts[0].y + num.1 * inv,
        verts[0].z + num.2 * inv,
    ))
}

/// Compute mesh quality statistics
pub fn compute_quality(mesh: &Mesh) -> (f64, f64, usize) {
    let mut min_quality: f64 = f64::INFINITY;
    let mut max_quality: f64 = 0.0;
    let mut num_slivers = 0;
    let mut num_tets = 0;

    for elem in &mesh.elements {
        if elem.element_type != ElementType::Tetrahedron {
            continue;
        }
        num_tets += 1;

        let verts: [Point; 4] = [
            mesh.nodes[elem.nodes[0]],
            mesh.nodes[elem.nodes[1]],
            mesh.nodes[elem.nodes[2]],
            mesh.nodes[elem.nodes[3]],
        ];

        let quality = tetrahedron_quality(&verts);
        min_quality = min_quality.min(quality);
        max_quality = max_quality.max(quality);

        if quality > 2.0 {
            num_slivers += 1;
        }
    }

    if num_tets == 0 {
        return (0.0, 0.0, 0);
    }

    (min_quality, max_quality, num_slivers)
}
